class EncryptionUtils:
    ALPHABET_SIZE = 26
    ASCII_UPPER_A = 65
    LOWER_A_ORD = ord('a')
    UPPER_A_ORD = ord('A')

    def __init__(self, key):
        self._key = key

    @property
    def key(self):
        return self._key

    @key.setter
    def key(self, value):
        self._key = value

    def caesar_cipher(self, plaintext, shift):
        return ''.join(self._caesar_shift_char(char, shift) for char in plaintext)

    def _caesar_shift_char(self, char, shift):
        if char.isalpha():
            ascii_offset = self.ASCII_UPPER_A if char.isupper() else self.LOWER_A_ORD
            return chr((ord(char) - ascii_offset + shift) % self.ALPHABET_SIZE + ascii_offset)
        return char

    def vigenere_cipher(self, plain_text):
        return ''.join(self._vigenere_encrypt_char(char, key_index) for char, key_index in self._iter_key_indices(plain_text))

    def _iter_key_indices(self, plain_text):
        key_index = 0
        for char in plain_text:
            if char.isalpha():
                yield char, key_index
                key_index += 1
            else:
                yield char, None

    def _vigenere_encrypt_char(self, char, key_index):
        if not char.isalpha() or key_index is None:
            return char
        shift = ord(self.key[key_index % len(self.key)].lower()) - self.LOWER_A_ORD
        encrypted_char = chr((ord(char.lower()) - self.LOWER_A_ORD + shift) % self.ALPHABET_SIZE + self.LOWER_A_ORD)
        return encrypted_char.upper() if char.isupper() else encrypted_char

    def rail_fence_cipher(self, plain_text, rails):
        fence = self._build_fence(plain_text, rails)
        return self._read_fence(fence, len(plain_text))

    def _build_fence(self, plain_text, rails):
        fence = [['\n' for _ in range(len(plain_text))] for _ in range(rails)]
        direction = -1
        row, col = 0, 0

        for char in plain_text:
            if row == 0 or row == rails - 1:
                direction = -direction

            fence[row][col] = char
            col += 1
            row += direction

        return fence

    def _read_fence(self, fence, text_length):
        encrypted_text = ''
        for row in range(len(fence)):
            for col in range(text_length):
                if fence[row][col] != '\n':
                    encrypted_text += fence[row][col]
        return encrypted_text
